package com.security.__PKG__.ui.components

// Canonical source: android-foundation/design-system/components/GlassFab.kt
// (CallUp's floating "+" button, reworked). Copied into every app generated by `app`, with
// __PKG__ replaced. Improve it in android-foundation, not in a single app.

import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.size
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.material3.Icon
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.semantics.Role
import androidx.compose.ui.unit.dp
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Shape
import com.kyant.backdrop.Backdrop
import com.kyant.backdrop.backdrops.LayerBackdrop
import com.kyant.backdrop.backdrops.rememberCombinedBackdrop
import com.kyant.backdrop.backdrops.rememberLayerBackdrop
import com.kyant.backdrop.drawBackdrop
import com.kyant.backdrop.effects.blur
import com.security.__PKG__.ui.theme.Accent
import com.security.__PKG__.ui.theme.BgPrimary
import com.security.__PKG__.ui.theme.LocalScreenBackdrop
import com.security.__PKG__.ui.theme.wallpaperBackdropActive

/**
 * Records the content that scrolls under a [GlassFab], so the button can blur it. Apply it to that
 * content with `Modifier.layerBackdrop(fabBackdrop)` — never to a parent of the button itself.
 * Without a wallpaper the recording gets the page background first: the blurred copy is then fully
 * opaque, so no sharp content shows through the button's soft edges.
 */
@Composable
fun rememberGlassFabBackdrop(): LayerBackdrop = rememberLayerBackdrop {
    if (!wallpaperBackdropActive) drawRect(BgPrimary)
    drawContent()
}

/**
 * Floating round action button with a see-through, blurred background: it shows a blurred copy of
 * whatever sits behind it (the content recorded by [rememberGlassFabBackdrop], plus the wallpaper
 * when liquid glass is on), under a 12 % accent wash and a 50 % accent outline — the same look as
 * the selected pill of the stats switcher.
 *
 * Replaces CallUp's first version, which sat on an opaque BgCard disc and so was never transparent.
 */
@Composable
fun GlassFab(
    onClick: () -> Unit,
    icon: ImageVector,
    contentDescription: String,
    backdrop: LayerBackdrop,
    modifier: Modifier = Modifier,
) {
    val wallpaper = LocalScreenBackdrop.current?.takeIf { wallpaperBackdropActive }
    val source = if (wallpaper != null) rememberCombinedBackdrop(wallpaper, backdrop) else backdrop
    Box(
        modifier = modifier
            .padding(16.dp)
            .size(56.dp)
            .glassFabSurface(source, CircleShape)
            .clip(CircleShape)
            .clickable(role = Role.Button, onClick = onClick),
        contentAlignment = Alignment.Center,
    ) {
        Icon(icon, contentDescription = contentDescription, tint = Accent)
    }
}

/**
 * The [GlassFab] look as a reusable background: 12 dp blur of [backdrop], 12 % accent wash, 50 %
 * accent outline. Apply it to a background-only layer (`Modifier.matchParentSize()` behind the
 * content) — the blur wraps everything its own node draws, so text on that node would blur too.
 * Also the look of every card when a wallpaper is shown with liquid glass OFF (see
 * design-system/liquid-glass.md §5.4) — one source for the "+" button and the cards. Those cards
 * pass the gray `Border` token as [borderColor]; the button keeps the accent outline. A fully
 * transparent [borderColor] (menus, dialogs) also drops drawBackdrop's default edge highlight,
 * which otherwise still reads as a thin light outline.
 */
fun Modifier.glassFabSurface(
    backdrop: Backdrop,
    shape: Shape,
    borderColor: Color = Accent.copy(alpha = 0.5f),
): Modifier {
    if (borderColor.alpha == 0f) {
        return drawBackdrop(
            backdrop = backdrop,
            shape = { shape },
            effects = { blur(12.dp.toPx()) },
            highlight = { null },
            onDrawSurface = { drawRect(Accent.copy(alpha = 0.12f)) },
        )
    }
    return this
        .drawBackdrop(
            backdrop = backdrop,
            shape = { shape },
            effects = { blur(12.dp.toPx()) },
            onDrawSurface = { drawRect(Accent.copy(alpha = 0.12f)) },
        )
        .border(1.dp, borderColor, shape)
}
